// Applies the DDL generated by `npm run db:sql` (prisma/schema.sql) to Neon
// over HTTPS, using the Neon serverless HTTP driver — no direct Postgres
// TCP connection is needed, so this works from networks that only pass
// HTTPS (like this VM). Usage:
//   npm run db:sql     # regenerate prisma/schema.sql from prisma/schema.prisma
//   npm run db:apply   # apply it
import { readFileSync } from "node:fs";
import { neon } from "@neondatabase/serverless";

async function main(): Promise<void> {
  const file = process.argv[2] ?? "prisma/schema.sql";
  const sqlText = readFileSync(file, "utf8");
  const sql = neon(process.env.DATABASE_URL!);

  const statements: string[] = sqlText
    .split(/;\s*\n/)
    .map((s) =>
      s
        .split("\n")
        .filter((line) => !line.trim().startsWith("--"))
        .join("\n")
        .trim(),
    )
    .filter(Boolean);

  function isTransient(e: unknown): boolean {
    const err = e as { message?: string; sourceError?: { message?: string }; cause?: { code?: string } };
    const text = `${err?.message ?? ""} ${err?.sourceError?.message ?? ""} ${err?.cause?.code ?? ""}`;
    return /fetch failed|other side closed|UND_ERR_SOCKET|ECONNRESET|ETIMEDOUT/i.test(text);
  }

  async function runWithRetry(stmt: string, attempts = 4): Promise<void> {
    let lastErr: unknown;
    for (let i = 1; i <= attempts; i++) {
      try {
        await sql.query(stmt);
        return;
      } catch (e) {
        lastErr = e;
        if (!isTransient(e) || i === attempts) throw e;
        await new Promise((r) => setTimeout(r, 2000 * i));
      }
    }
    throw lastErr;
  }

  for (const stmt of statements) {
    try {
      await runWithRetry(stmt);
      console.log("OK:", stmt.slice(0, 90).replace(/\s+/g, " "));
    } catch (e) {
      // Re-runnable: an object created by an earlier partial run is fine.
      if (e && /already exists/i.test((e as Error).message ?? "")) {
        console.log("SKIP (already exists):", stmt.slice(0, 90).replace(/\s+/g, " "));
        continue;
      }
      throw e;
    }
  }

  const tables = (await sql`
    SELECT table_name FROM information_schema.tables
    WHERE table_schema = 'public' ORDER BY 1
  `) as Array<{ table_name: string }>;
  console.log(`Applied ${statements.length} statements from ${file}.`);
  console.log(
    "Tables now in public schema:",
    tables.map((t) => t.table_name).join(", "),
  );
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
